'use client';

import type { User } from '@openfort/openfort-js';
import { useUser } from '@openfort/react';
import {
  exchangeOpenfortSession,
  getBackendMe,
  logoutBackendSession,
  refreshBackendSession,
  type BackendMeResponse,
} from '@/lib/backend-auth-client';
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';

type AppSessionStatus =
  | 'idle'
  | 'loading'
  | 'authenticated'
  | 'unauthenticated'
  | 'error';

interface AuthSessionContextValue {
  status: AppSessionStatus;
  backendAccessToken: string | null;
  backendUser: BackendMeResponse | null;
  openfortUser: User | null;
  isOpenfortLoading: boolean;
  isOpenfortAuthenticated: boolean;
  error: string | null;
  retry: () => void;
}

const AuthSessionContext = createContext<AuthSessionContextValue | null>(null);

function getErrorMessage(error: unknown) {
  if (error instanceof Error && error.message) {
    return error.message;
  }

  return 'Failed to initialize your session.';
}

export function AuthSessionProvider({ children }: { children: ReactNode }) {
  const { user, isLoading, isAuthenticated, getAccessToken } = useUser();
  const openfortUserId = user?.id ?? null;
  const [status, setStatus] = useState<AppSessionStatus>('idle');
  const [backendAccessToken, setBackendAccessToken] = useState<string | null>(
    null
  );
  const [backendUser, setBackendUser] = useState<BackendMeResponse | null>(
    null
  );
  const [error, setError] = useState<string | null>(null);
  const [retryCount, setRetryCount] = useState(0);
  const previousAuthState = useRef(false);

  const clearSession = useCallback(() => {
    setBackendAccessToken(null);
    setBackendUser(null);
    setError(null);
  }, []);

  const bootstrapSession = useCallback(async () => {
    if (!openfortUserId) {
      clearSession();
      setStatus('unauthenticated');
      return;
    }

    setStatus('loading');
    setError(null);

    try {
      const loginResponse =
        (await refreshBackendSession().catch(() => null)) ??
        (await (async () => {
          const openfortAccessToken = await getAccessToken();

          if (!openfortAccessToken) {
            throw new Error('Openfort access token is unavailable.');
          }

          return exchangeOpenfortSession(openfortAccessToken);
        })());

      const me = await getBackendMe(loginResponse.access_token);

      setBackendAccessToken(loginResponse.access_token);
      setBackendUser(me);
      setStatus('authenticated');
    } catch (sessionError) {
      clearSession();
      setError(getErrorMessage(sessionError));
      setStatus('error');
    }
  }, [clearSession, getAccessToken, openfortUserId]);

  useEffect(() => {
    if (isLoading) {
      setStatus((currentStatus) =>
        currentStatus === 'authenticated' ? currentStatus : 'loading'
      );
      return;
    }

    if (!isAuthenticated || !openfortUserId) {
      clearSession();
      setStatus('unauthenticated');
      return;
    }

    void bootstrapSession();
  }, [
    bootstrapSession,
    clearSession,
    isAuthenticated,
    isLoading,
    openfortUserId,
    retryCount,
  ]);

  useEffect(() => {
    const signedOut =
      previousAuthState.current && !isLoading && !isAuthenticated;

    previousAuthState.current = isAuthenticated;

    if (!signedOut) {
      return;
    }

    clearSession();
    setStatus('unauthenticated');
    void logoutBackendSession().catch(() => undefined);
  }, [clearSession, isAuthenticated, isLoading]);

  const value = useMemo<AuthSessionContextValue>(
    () => ({
      status,
      backendAccessToken,
      backendUser,
      openfortUser: user,
      isOpenfortLoading: isLoading,
      isOpenfortAuthenticated: isAuthenticated,
      error,
      retry: () => setRetryCount((count) => count + 1),
    }),
    [
      status,
      backendAccessToken,
      backendUser,
      user,
      isLoading,
      isAuthenticated,
      error,
    ]
  );

  return (
    <AuthSessionContext.Provider value={value}>
      {children}
    </AuthSessionContext.Provider>
  );
}

export function useAuthSession() {
  const context = useContext(AuthSessionContext);

  if (!context) {
    throw new Error(
      'useAuthSession must be used within an AuthSessionProvider.'
    );
  }

  return context;
}

'use client';
import type React from 'react';
import AppSidebar from './sidebar';
import Header from './header';
import { usePathname, useRouter } from 'next/navigation';
import { useEffect } from 'react';
import { AuthErrorState, AuthLoadingState } from './auth/auth-state';
import { useAuthSession } from './auth/auth-session-provider';

interface MainLayoutProps {
  children: React.ReactNode;
}

export function MainLayout({ children }: MainLayoutProps) {
  const pathname = usePathname();
  const router = useRouter();
  const isAuthPage = pathname?.startsWith('/login');
  const { status, error, retry, isOpenfortAuthenticated, isOpenfortLoading } =
    useAuthSession();

  useEffect(() => {
    if (isOpenfortLoading || !pathname) {
      return;
    }

    if (isAuthPage) {
      if (status === 'authenticated') {
        router.replace('/home');
      }

      return;
    }

    if (!isOpenfortAuthenticated) {
      router.replace('/login');
    }
  }, [
    isAuthPage,
    isOpenfortAuthenticated,
    isOpenfortLoading,
    pathname,
    router,
    status,
  ]);

  const showAuthLoading =
    isOpenfortLoading ||
    (isAuthPage
      ? isOpenfortAuthenticated && status !== 'error'
      : !isOpenfortAuthenticated || status === 'loading' || status === 'idle');

  return (
    <div className="relative min-h-screen overflow-hidden bg-[#0C0C0D]">
      {/* Background circles */}
      <div className="fixed inset-0 pointer-events-none z-0">
        <div className="absolute -top-32 -right-32 opacity-50 w-[662px] h-[662px] rounded-full blur-3xl bg-[#1A2A4AAD]" />
        <div className="absolute -bottom-44 -left-32 opacity-50 w-[662px] h-[662px] rounded-full blur-3xl bg-[#1A2A4AAD]" />
      </div>

      {/* Main content */}
      {isAuthPage ? (
        <div className="relative z-[999] flex items-center justify-center min-h-screen p-4">
          {showAuthLoading ? (
            <AuthLoadingState message="Checking your Openfort session..." />
          ) : status === 'error' ? (
            <AuthErrorState
              message={error || 'Unable to continue.'}
              onRetry={retry}
            />
          ) : (
            children
          )}
        </div>
      ) : (
        <div className="relative z-[999] flex min-h-screen items-center justify-center p-4 md:p-8 lg:p-12">
          {showAuthLoading ? (
            <AuthLoadingState message="Restoring your InfraFund session..." />
          ) : status === 'error' ? (
            <AuthErrorState
              message={error || 'Unable to continue.'}
              onRetry={retry}
            />
          ) : (
            <div className="relative z-[999] flex p-4 md:p-8 lg:p-12 gap-4 md:gap-8 lg:gap-12 min-h-screen w-full">
              <div className="h-full -mt-3.5">
                <AppSidebar />
              </div>
              <div className="flex-1">
                <div className="flex flex-col h-fit px-12 gap-12">
                  <Header />
                  <main className="flex-1 backdrop-blur-sm rounded-lg">
                    {children}
                  </main>
                </div>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

'use client';

import { Bell, Headset } from 'lucide-react';
import { OpenfortButton } from '@openfort/react';
import { usePathname } from 'next/navigation';
import { useMemo } from 'react';
import { useAuthSession } from './auth/auth-session-provider';

const routeTitles: Record<string, string> = {
  '/': 'Dashboard',
  '/home': 'Dashboard',
  '/explore-projects': 'Explore Projects',
  '/create-project': 'Create Project',
  '/tokenization': 'Tokenization',
  '/investment-portal': 'Investment Portal',
  '/digital-assets': 'Digital Assets',
  '/investor-management': 'Investor Management',
  '/investment-requests': 'Investment Requests',
  '/asset-management': 'Asset Management',
  '/swap': 'Swap',
  '/kyc': 'KYC',
};

export default function Header() {
  const pathname = usePathname();
  const { backendUser, openfortUser } = useAuthSession();
  const pageTitle = routeTitles[pathname] || 'Page';
  const displayName = useMemo(() => {
    const fullName = [backendUser?.first_name, backendUser?.last_name]
      .filter(Boolean)
      .join(' ')
      .trim();

    return fullName || openfortUser?.name || openfortUser?.email || 'User';
  }, [
    backendUser?.first_name,
    backendUser?.last_name,
    openfortUser?.email,
    openfortUser?.name,
  ]);

  const secondaryLabel =
    openfortUser?.email || backendUser?.role || openfortUser?.id || 'Openfort';
  const avatarLabel = displayName.charAt(0).toUpperCase();

  return (
    <div className="flex h-16 shrink-0 justify-between items-center sticky top-0 z-20 rounded-lg mb-4">
      <div className="flex flex-col gap-2">
        <span className="text-sm font-normal text-white leading-2">
          Hi {displayName}
          <span className="text-[#8087A3] text-base font-normal">
            {' '}
            - {secondaryLabel}
          </span>
        </span>
        <span className="text-[40px] font-bold text-white">{pageTitle}</span>
      </div>

      <div className="flex justify-center items-center gap-4">
        <Headset size={24} className="text-white cursor-pointer" />
        <Bell size={24} className="text-white cursor-pointer" />
        <OpenfortButton label="Wallet" showAvatar />
        <div className="w-12 h-12 rounded-full bg-[#263247] flex justify-center items-center text-white">
          {avatarLabel}
        </div>
      </div>
    </div>
  );
}

'use client';

interface BackendLoginResponse {
  user_id: string;
  access_token: string;
  expires_at: string;
}

export interface BackendMeResponse {
  user_id: string;
  openfort_user_id: string;
  email: string | null;
  first_name: string | null;
  last_name: string | null;
  company_name: string | null;
  phone_number: string | null;
  type: string;
  role: string;
  status: string;
  kyc_verified: boolean;
  kyb_verified: boolean;
}

interface SuccessResponse<T> {
  code: string;
  data: T;
}

interface ErrorResponse {
  message?: string;
}

function getApiBaseUrl() {
  return (
    process.env.NEXT_PUBLIC_API_BASE_URL ??
    process.env.NEXT_PUBLIC_BASE_URL ??
    ''
  ).replace(/\/+$/, '');
}

function buildUrl(path: string) {
  const normalizedPath = path.replace(/^\/+/, '');
  const baseUrl = getApiBaseUrl();

  return baseUrl ? `${baseUrl}/${normalizedPath}` : `/v1/${normalizedPath}`;
}

async function request<T>(
  path: string,
  init: RequestInit & { accessToken?: string } = {}
) {
  const headers = new Headers(init.headers);

  if (init.body && !headers.has('Content-Type')) {
    headers.set('Content-Type', 'application/json');
  }

  if (init.accessToken) {
    headers.set('Authorization', `Bearer ${init.accessToken}`);
  }

  const response = await fetch(buildUrl(path), {
    ...init,
    headers,
    credentials: 'include',
  });

  if (!response.ok) {
    let message = 'Request failed';

    try {
      const errorBody = (await response.json()) as ErrorResponse;
      message = errorBody.message || message;
    } catch {}

    throw new Error(message);
  }

  if (response.status === 204) {
    return null as T;
  }

  const body = (await response.json()) as SuccessResponse<T>;
  return body.data;
}

export async function exchangeOpenfortSession(openfortAccessToken: string) {
  return request<BackendLoginResponse>('auth/openfort/exchange', {
    method: 'POST',
    accessToken: openfortAccessToken,
  });
}

export async function refreshBackendSession() {
  return request<BackendLoginResponse>('auth/refresh', {
    method: 'POST',
  });
}

export async function getBackendMe(accessToken: string) {
  return request<BackendMeResponse>('me', {
    method: 'GET',
    accessToken,
  });
}

export async function logoutBackendSession() {
  await request<null>('auth/logout', {
    method: 'POST',
  });
}

'use client';

import { OpenfortProvider, AuthProvider } from '@openfort/react';
import { getDefaultConfig, OpenfortWagmiBridge } from '@openfort/react/wagmi';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { baseSepolia, base } from 'viem/chains';
import { createConfig, WagmiProvider } from 'wagmi';
import type { ReactNode } from 'react';
import { AuthSessionProvider } from '@/components/auth/auth-session-provider';

const publishableKey = process.env.NEXT_PUBLIC_OPENFORT_PUBLIC_KEY;
const shieldPublishableKey = process.env.NEXT_PUBLIC_SHIELD_API_KEY;

const wagmiConfig = createConfig(
  getDefaultConfig({
    appName: 'InfraFund',
    chains: [baseSepolia, base],
    walletConnectProjectId:
      process.env.NEXT_PUBLIC_WALLET_CONNECT_PROJECT_ID || '',
  })
);

const queryClient = new QueryClient();

function OpenfortNotConfigured() {
  return (
    <div className="rounded-lg border border-yellow-500 bg-yellow-900/20 p-4 text-left text-sm text-yellow-100 max-w-md mx-auto mt-10">
      <p className="font-semibold">Openfort is not configured.</p>
      <p className="mt-2">
        Add <code>NEXT_PUBLIC_OPENFORT_PUBLIC_KEY</code> and{' '}
        <code>NEXT_PUBLIC_SHIELD_API_KEY</code> to your <code>.env.local</code>{' '}
        file.
      </p>
    </div>
  );
}

export function AppProviders({ children }: { children: ReactNode }) {
  if (!publishableKey || !shieldPublishableKey) {
    return (
      <QueryClientProvider client={queryClient}>
        <OpenfortNotConfigured />
      </QueryClientProvider>
    );
  }

  return (
    <QueryClientProvider client={queryClient}>
      <WagmiProvider config={wagmiConfig}>
        <OpenfortWagmiBridge>
          <OpenfortProvider
            publishableKey={publishableKey}
            walletConfig={{
              shieldPublishableKey,
              ethereum: {
                ethereumFeeSponsorshipId:
                  process.env.NEXT_PUBLIC_POLICY_ID || undefined,
              },
              connectOnLogin: true,
              createEncryptedSessionEndpoint: '/api/auth/encryption-session',
            }}
            uiConfig={{
              theme: 'midnight',
              mode: 'dark',
              authProviders: [AuthProvider.GOOGLE, AuthProvider.EMAIL_OTP],
            }}
          >
            <AuthSessionProvider>{children}</AuthSessionProvider>
          </OpenfortProvider>
        </OpenfortWagmiBridge>
      </WagmiProvider>
    </QueryClientProvider>
  );
}

