package postgres

import (
	"context"

	"github.com/InfraFund-net7/backpro/internal/domain/wallet/entity"
	"github.com/InfraFund-net7/backpro/internal/domain/wallet/repository"
	"github.com/InfraFund-net7/backpro/internal/infrastructure/persistence/postgres/gen"
	"github.com/InfraFund-net7/backpro/pkg/logger"
	"github.com/google/uuid"
)

var _ repository.WalletRepo = (*WalletRepo)(nil)

type WalletRepo struct {
	db     *Database
	logger *logger.SubLogger
}

func NewWalletRepo(db *Database) *WalletRepo {
	return &WalletRepo{
		db:     db,
		logger: db.logging,
	}
}

func (w *WalletRepo) Create(ctx context.Context, wallet *entity.Wallet) error {
	w.logger.Debug("WalletRepo.Create", "user_id", wallet.UserID, "chain", wallet.Chain)

	return w.db.Queries(ctx).CreateWallet(ctx, gen.CreateWalletParams{
		UserID:        wallet.UserID,
		PublicAddress: wallet.PublicAddress,
		Chain:         wallet.Chain.String(),
	})
}

func (w *WalletRepo) CreateBatchWallets(ctx context.Context, wallets []*entity.Wallet) (int64, error) {
	w.logger.Debug("WalletRepo.CreateBatchWallets")

	raws := make([]gen.CreateBatchWalletsParams, 0, len(wallets))
	for _, wallet := range wallets {
		raws = append(raws, gen.CreateBatchWalletsParams{
			UserID:        wallet.UserID,
			PublicAddress: wallet.PublicAddress,
			Chain:         wallet.Chain.String(),
		})
	}

	return w.db.Queries(ctx).CreateBatchWallets(ctx, raws)
}

func (w *WalletRepo) GetCount(ctx context.Context, userID uuid.UUID) (int64, error) {
	w.logger.Debug("WalletRepo.GetCount", "user_id", userID)

	return w.db.Queries(ctx).GetWalletCount(ctx, userID)
}

func (w *WalletRepo) ListUserWallets(ctx context.Context, userID uuid.UUID) ([]*entity.Wallet, error) {
	w.logger.Debug("WalletRepo.ListUserWallets", "user_id", userID)

	raws, err := w.db.Queries(ctx).ListUserWallets(ctx, userID)
	if err != nil {
		return nil, err
	}

	wallets := make([]*entity.Wallet, 0, len(raws))
	for _, raw := range raws {
		wallets = append(wallets, mapWalletToDomain(raw))
	}

	return wallets, nil
}

