package router

import (
	"github.com/InfraFund-net7/backpro/internal/interfaces/rest/handler"
	"github.com/InfraFund-net7/backpro/internal/interfaces/rest/middleware"
	"github.com/danielgtaylor/huma/v2"
	"github.com/gofiber/fiber/v2"
)

func (r *Router) setupWaitList(wh *handler.WaitlistHandler) {
	wl := huma.NewGroup(r.v1, "/waitlists")

	huma.Register(wl, huma.Operation{
		OperationID: "CreateWaitlist",
		Summary:     "Create Waitlist",
		Description: "Create a waitlist entry.",
		Method:      fiber.MethodPost,
		Path:        "",
		Tags:        []string{"Non-Registration Forms"},
		Middlewares: huma.Middlewares{middleware.Recaptcha(r.api, r.rcap)},
		Errors:      []int{500},
	}, wh.Create)
}

package handler

import (
	"context"

	"github.com/InfraFund-net7/backpro/internal/domain/shared"
	"github.com/InfraFund-net7/backpro/internal/domain/waitlist/service"
	"github.com/InfraFund-net7/backpro/internal/interfaces/rest/input"
	"github.com/InfraFund-net7/backpro/internal/interfaces/rest/output"
)

type WaitlistHandler struct {
	svc service.WaitListService
}

func NewWaitlistHandler(svc service.WaitListService) *WaitlistHandler {
	return &WaitlistHandler{svc: svc}
}

func (wh *WaitlistHandler) Create(ctx context.Context,
	in *input.CreateWaitlistInput,
) (*output.SuccessEmptyOutput, error) {
	err := wh.svc.Create(ctx, shared.NewEmail(in.Body.Email))
	if err != nil {
		return nil, output.NewErrorOutput(err)
	}

	return output.NewSuccessEmptyOutput(), nil
}

package input

type CreateWaitlistInput struct {
	ChallengeKey string `header:"X-Captcha-Token" minLength:"1" maxLength:"500"`
	Body         CreateWaitlistBody
}

type CreateWaitlistBody struct {
	Email string `json:"email" format:"email" required:"true" minLength:"5" maxLength:"255" example:"example@gmail.com"`
}

package waitlist

import (
	"context"

	"github.com/InfraFund-net7/backpro/internal/domain/shared"
	"github.com/InfraFund-net7/backpro/internal/domain/waitlist"
	"github.com/InfraFund-net7/backpro/internal/domain/waitlist/repository"
	"github.com/InfraFund-net7/backpro/internal/domain/waitlist/service"
	"github.com/InfraFund-net7/backpro/pkg/errs"
	"github.com/InfraFund-net7/backpro/pkg/logger"
)

var _ service.WaitListService = (*Waitlist)(nil)

type Waitlist struct {
	waitListRepo repository.WaitlistRepo
	logger       *logger.SubLogger
}

func NewWaitlistService(waitListRepo repository.WaitlistRepo) *Waitlist {
	return &Waitlist{
		waitListRepo: waitListRepo,
		logger:       logger.NewBusinessLogger("waitlist"),
	}
}

func (*Waitlist) String() string {
	return "Waitlist"
}

func (w *Waitlist) Create(ctx context.Context, email shared.Email) error {
	exists, err := w.waitListRepo.EmailExists(ctx, email)
	if err != nil {
		w.logger.Error("failed to check if email exists", "email", email, "error", err)

		return errs.NewAppError(errs.Database, "failed to check if email exists", 500).WithError(err)
	}

	if exists {
		return waitlist.ErrEmailExists
	}

	if err := w.waitListRepo.Create(ctx, email); err != nil {
		w.logger.Error("failed to create waitlist entry", "email", email, "error", err)

		return errs.NewAppError(errs.Database, "failed to create waitlist entry", 500).WithError(err)
	}

	return nil
}

