            </div>
            <p className="text-gray-700 mb-4">{errorModal}</p>
            <button
              type="button"
              onClick={() => setErrorModal(null)}
              className="w-full bg-red-600 text-white py-2 px-4 rounded hover:bg-red-700"
            >
              Close
            </button>
          </div>
        </div>
      )}
    </>
  )
}

